import React, { useRef } from 'react';
import { confirmDialog } from 'primereact/confirmdialog';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';

export default function Basic() {
    const toast = useRef(null);

    const accept = () => {
        toast.current.show({ className: 'info', summary: 'Confirmed', detail: 'You have accepted', life: 3000 });
    }

    const reject = () => {
        toast.current.show({ className: 'warn', summary: 'Rejected', detail: 'You have rejected', life: 3000 });
    }

    const confirm1 = () => {
        confirmDialog({
            message: 'Are you sure you want to proceed?',
            header: 'Confirmation',
            icon: 'pi pi-exclamation-triangle',
            defaultFocus: 'accept',
            rejectClassName: 'text',
            accept,
            reject
        });
    };

    const confirm2 = () => {
        confirmDialog({
            message: 'Do you want to delete this record?',
            header: 'Delete Confirmation',
            icon: 'pi pi-info-circle',
            defaultFocus: 'reject',
            acceptClassName: 'danger',
            rejectClassName: 'text',
            accept,
            reject
        });
    };

    return (
        <>
            <Toast ref={toast} />
            <Button onClick={confirm1} icon="pi pi-check" label="Confirm" className="mgr6"></Button>
            <Button onClick={confirm2} outlined severity="danger" icon="pi pi-times" label="Delete"></Button>
        </>
    )

}